css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .56); position: relative; display: grid; grid-template-columns: repeat(4, 1fr); grid-template-rows: repeat(2, 1fr); gap: 5%; padding: 4%; border-radius: 8px; background: color-mix(in srgb, var(--accent) 16%, transparent); box-sizing: border-box; }
.loader span { position: relative; border-radius: 40% / 46%; background: linear-gradient(150deg, color-mix(in srgb, #fff 45%, var(--accent-2)), var(--accent-2)); box-shadow: inset 0 -3px 0 color-mix(in srgb, #000 12%, transparent); animation: blister-pop calc(var(--loader-speed) * 2.8) ease-in-out infinite; }
.loader span::after { content: ''; position: absolute; left: 26%; right: 26%; top: 38%; height: 22%; border-radius: 999px; background: var(--accent); }
.loader span:nth-of-type(2) { animation-delay: calc(var(--loader-speed) * .28); }
.loader span:nth-of-type(3) { animation-delay: calc(var(--loader-speed) * .56); }
.loader span:nth-of-type(4) { animation-delay: calc(var(--loader-speed) * .84); }
.loader span:nth-of-type(5) { animation-delay: calc(var(--loader-speed) * 1.12); }
.loader span:nth-of-type(6) { animation-delay: calc(var(--loader-speed) * 1.4); }
.loader span:nth-of-type(7) { animation-delay: calc(var(--loader-speed) * 1.68); }
.loader span:nth-of-type(8) { animation-delay: calc(var(--loader-speed) * 1.96); }
@keyframes blister-pop { 0%, 10% { transform: scale(1); opacity: 1; } 18% { transform: scale(1.16); } 26%, 74% { transform: scale(.62); opacity: .3; } 88%, 100% { transform: scale(1); opacity: 1; } }
